/** 座位 id（设置导航里的稳定标识）。 */
const SECTION_ID = 'retry-backoff';
/** 与宿主 `lib/routes.js` 的 BASE 同源。 */
const BASE = '/retry-backoff';

/** 本地预览用的设置副本；面板渲染与预览曲线都读它。 */
